101	
102	    /** Number of owners already in a city at or above which a new owner is flagged as approaching the per-city capacity limit. */
103	    static final long CAPACITY_WARNING_THRESHOLD = 40;
104	
105	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
106	    static final long MAX_OWNERS_PER_DAY = 100;
107	
108	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
109	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
