219	    /**
220	     * Canonicalize the request's address fields in place, preferring the structured form. When a
221	     * non-blank {@code addressLine1} is supplied it and the optional {@code addressLine2} are
222	     * normalized and the composed value stored on {@code address}; otherwise only the flat
223	     * {@code address} is normalized. This keeps the stored {@code address} the single canonical
224	     * value everything downstream reads.
225	     */
226	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
227	        if (ownerFieldsDto.getAddressLine1() != null && !ownerFieldsDto.getAddressLine1().isBlank()) {
228	            ownerFieldsDto.setAddressLine1(this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine1()));
229	            String line2 = this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
230	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
231	            ownerFieldsDto.setAddress(
232	                this.addressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
233	        }
234	        else {
235	            ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
236	        }
237	    }
