249	        currentOwner.setLastName(ownerFieldsDto.getLastName());
250	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
251	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
252	        this.clinicService.saveOwner(currentOwner);
253	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
254	    }
