239	    @Override
240	    @Transactional
241	    public void saveOwner(Owner owner) throws DataAccessException {
242	        if (owner.isNew() && owner.getMemberId() == null) {
243	            String region = LocalityResolver.regionFor(owner.getPostcode(), owner.getCity());
244	            String memberId = memberIdGenerator.generate(
245	                region, owner.getTelephone(), owner.getLastName(), owner.getRegistrationDate());
246	            owner.setMemberId(deduplicateMemberId(memberId));
247	        }
248	        if (owner.isNew() && owner.getNamesakeCount() == null) {
249	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
250	        }
251	        if (owner.isNew() && owner.getHouseholdSize() == null) {
252	            owner.setHouseholdSize(countHouseholdMembers(owner));
253	        }
254	        if (owner.isNew() && owner.getMembershipLevelCap() == null) {
