397	    /** Points awarded when an email address is present. */
398	    private static final int EMAIL_POINTS = 2;
399	
400	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
401	    private static final int NO_NAMESAKE_POINTS = 1;
402	
403	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
404	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
405	
406	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
407	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
408	
409	    /** Points awarded for qualifying tenure. */
410	    private static final int TENURE_POINTS = 3;
411	
412	    /** The tenure, in elapsed fiscal years, that must be exceeded to earn {@link #TENURE_POINTS}. */
413	    private static final long MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS = 1;
414	
415	    /**
416	     * Return this owner's membership points, starting at 0: add {@value #EMAIL_POINTS} when an email
417	     * address is present; add {@value #NO_NAMESAKE_POINTS} when the owner has no namesakes
418	     * ({@code namesakeCount} is 0); add {@value #LARGE_HOUSEHOLD_POINTS} for a household of
419	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
420	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed fiscal year since registration).
421	     */
422	    @Transient
423	    public Integer getMembershipPoints() {
424	        int points = 0;
425	        if (hasEmail()) {
426	            points += EMAIL_POINTS;
427	        }
428	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
429	            points += NO_NAMESAKE_POINTS;
430	        }
431	        if (hasLargeHousehold()) {
432	            points += LARGE_HOUSEHOLD_POINTS;
433	        }
434	        if (hasQualifyingTenure()) {
435	            points += TENURE_POINTS;
436	        }
437	        return points;
438	    }
439	
440	    /**
441	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
442	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then limited to the
443	     * owner's {@link #getMembershipLevelCap() membership-level ceiling} when one applies.
444	     */
445	    @Transient
446	    public Integer getMembershipLevel() {
447	        int level = membershipLevelFromPoints();
448	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
449	            return this.membershipLevelCap;
450	        }
451	        return level;
452	    }
453	
454	    /** Map this owner's {@link #getMembershipPoints() membership points} to the uncapped level. */
455	    private int membershipLevelFromPoints() {
456	        int points = getMembershipPoints();
457	        if (points <= 1) {
458	            return 1;
459	        }
460	        if (points <= 3) {
461	            return 2;
462	        }
463	        if (points <= 5) {
464	            return 3;
465	        }
466	        return 4;
467	    }
468	
469	    /**
470	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
471	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
472	     * qualify.
473	     */
474	    private boolean hasLargeHousehold() {
475	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
476	    }
477	
478	    /**
479	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed
480	     * fiscal year, i.e. more than that many fiscal years have elapsed between the fiscal year of the
481	     * {@code registrationDate} and the fiscal year of today. Owners without a registration date have
482	     * no measurable tenure and do not qualify.
483	     */
484	    private boolean hasQualifyingTenure() {
485	        if (this.registrationDate == null) {
486	            return false;
487	        }
488	        long elapsedFiscalYears = FiscalYear.of(this.registrationDate).yearsUntil(FiscalYear.of(LocalDate.now()));
489	        return elapsedFiscalYears > MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS;
490	    }
