518	    /**
519	     * Return this owner's locality: the region code resolved from the postcode (preferred, matched
520	     * against the known region ranges) falling back to the city-to-region table, or {@code "UNKNOWN"}
521	     * when neither yields a region. This is the plain region code (for example {@code NSW}); the
522	     * identifiers instead lead with the {@link OwnerIdentityVersion#identityRegion(String) tagged
523	     * region}, so the version tag never appears in this user-facing value.
524	     */
525	    @Transient
526	    public String getLocality() {
