528	    }
529	
530	    /**
531	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
532	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
533	     * known timezone.
534	     */
535	    @Transient
536	    public String getTimezone() {
537	        return LocalityResolver.timezoneFor(getLocality());
538	    }
539	
540	    /**
541	     * Return this owner's segment, formatted {@code <TIER>_<AREA>}: the tier is {@code PREMIUM} when
542	     * the {@link #getMembershipLevel() membership level} is 3 or more, otherwise {@code STANDARD};
543	     * the area is {@code METRO} when the {@link #getLocality() locality} is a known region (NSW, VIC
544	     * or QLD), otherwise {@code REGIONAL}.
545	     */
546	    @Transient
547	    public String getOwnerSegment() {
548	        return OwnerSegment.of(getMembershipLevel(), getLocality());
549	    }
550	
551	    /**
552	     * Return this owner's identity key, the single derived value all duplicate detection is based
553	     * on: the lower-case SHA-256 hex digest over {@code normalizedTelephone + "|" + lowerEmail +
554	     * "|" + soundex(lastName)}, with an absent email rendered as the empty string. Two owners are
555	     * duplicates only when their whole identity keys are equal; because the telephone is part of
556	     * the key, two owners with the same last name and postcode but different telephones have
557	     * distinct keys and are not duplicates (they are instead flagged as a soft match).
558	     */
559	    @Transient
560	    public String getIdentityKey() {
561	        String core = keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + Soundex.encode(this.getLastName());
562	        return Sha256Hex.lowerHex(OwnerIdentityVersion.taggedInput(core));
563	    }
564	
565	    private static String keyPart(String value) {
566	        return value == null ? "" : value;
567	    }
