605	    /**
606	     * Return the Pet with the given name, or null if none found for this Owner.
607	     *
608	     * @param name to test
609	     * @return true if pet name is already in use
610	     */
611	    public Pet getPet(String name, boolean ignoreNew) {
612	        name = name.toLowerCase();
613	        for (Pet pet : getPetsInternal()) {
614	            if (!ignoreNew || !pet.isNew()) {
615	                String compName = pet.getName();
616	                compName = compName.toLowerCase();
617	                if (compName.equals(name)) {
618	                    return pet;
619	                }
620	            }
621	        }
622	        return null;
623	    }
