29	/**
30	 * Emits the audit trail for owner creation.
31	 *
32	 * <p>Successful creations are written to the dedicated {@code AUDIT} logger so the
33	 * side-effect can be routed and asserted independently of application logging. Each
34	 * creation emits both a human-readable audit line and an immutable structured
35	 * {@link OwnerCreatedEvent} serialized as JSON.
36	 */
37	@Component
38	public class OwnerAuditLogger {
39	
40	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
41	
42	    private static final ObjectMapper MAPPER = JsonMapper.builder().build();
43	
44	    /** Source of the monotonically increasing sequence number carried by each structured event. */
45	    private final AtomicLong sequence = new AtomicLong();
46	
47	    /**
48	     * Record that an owner was successfully created.
49	     *
50	     * @param owner the persisted owner, with its generated id, member id, registration date
51	     *              and membership level
52	     */
53	    public void logCreated(Owner owner) {
54	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
55	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
56	            owner.getMembershipLevel());
57	        OwnerCreatedEvent event = OwnerCreatedEvent.of(this.sequence.incrementAndGet(), owner);
58	        AUDIT.info(MAPPER.writeValueAsString(event));
59	    }
60	}
