18	
19	import java.util.Map;
20	import java.util.concurrent.ConcurrentHashMap;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Remembers which owner a client-supplied {@code Idempotency-Key} first created, so a repeated
26	 * create carrying the same key can return the original owner instead of inserting a duplicate.
27	 * Keys are optional: a {@code null} or blank key is never remembered and never matches.
28	 */
29	@Component
30	public class IdempotencyKeyRegistry {
31	
32	    private final Map<String, Integer> ownerIdByKey = new ConcurrentHashMap<>();
33	
34	    /**
35	     * Return the id of the owner previously created under {@code key}, or {@code null} if the key is
36	     * absent, blank, or has not been seen before.
37	     */
38	    public Integer findOwnerId(String key) {
39	        if (key == null || key.isBlank()) {
40	            return null;
41	        }
42	        return this.ownerIdByKey.get(key);
43	    }
44	
45	    /**
46	     * Associate {@code key} with the owner just created under it. No-op for a {@code null} or blank
47	     * key so unkeyed creates never occupy the registry.
48	     */
49	    public void remember(String key, Integer ownerId) {
50	        if (key != null && !key.isBlank()) {
51	            this.ownerIdByKey.putIfAbsent(key, ownerId);
52	        }
53	    }
54	}
