179	    /**
180	     * Handles {@link MissingOwnerFieldsException} raised when an owner request omits or
181	     * leaves blank one or more required fields. Returns a 400 Bad Request whose
182	     * {@code errors} array names each offending field.
183	     *
184	     * @param e The {@link MissingOwnerFieldsException} to be handled
185	     * @param request {@link HttpServletRequest} object referring to the current request.
186	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
187	     */
188	    @ExceptionHandler(MissingOwnerFieldsException.class)
189	    @ResponseBody
190	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
191	        HttpStatus status = HttpStatus.BAD_REQUEST;
192	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
193	        detail.setProperty("errors", e.getMissingFields());
194	        return ResponseEntity.status(status).body(detail);
195	    }
